// Turn approved queue rows into Tally import XML
const cfg = $('Set Sync Rules').first().json;
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const amt = n => (Math.round(Number(n) * 100) / 100).toFixed(2);
const company = cfg.tallyCompany ? `<STATICVARIABLES><SVCURRENTCOMPANY>${esc(cfg.tallyCompany)}</SVCURRENTCOMPANY></STATICVARIABLES>` : '';
const wrap = (report, body) => `<ENVELOPE><HEADER><TALLYREQUEST>Import Data</TALLYREQUEST></HEADER><BODY><IMPORTDATA>
<REQUESTDESC><REPORTNAME>${report}</REPORTNAME>${company}</REQUESTDESC>
<REQUESTDATA><TALLYMESSAGE xmlns:UDF="TallyUDF">${body}</TALLYMESSAGE></REQUESTDATA></IMPORTDATA></BODY></ENVELOPE>`;

const out = [];
$input.all().forEach((item, i) => {
  const r = item.json;
  let p;
  try { p = JSON.parse(r['Payload']); } catch (e) { p = null; }
  let xml = '', error = '';
  if (!p) error = 'Payload is not valid JSON';
  else if (p.action === 'Create') {
    const opt = (t, v) => (v ? `<${t}>${esc(v)}</${t}>` : '');
    xml = wrap('All Masters', `<LEDGER NAME="${esc(p.name)}" ACTION="Create">
<NAME.LIST><NAME>${esc(p.name)}</NAME></NAME.LIST>
<PARENT>${esc(p.parent || cfg.debtorGroup)}</PARENT>
<ISBILLWISEON>Yes</ISBILLWISEON>
${p.address ? `<ADDRESS.LIST TYPE="String"><ADDRESS>${esc(p.address)}</ADDRESS></ADDRESS.LIST>` : ''}
${opt('EMAIL', p.email)}${opt('LEDGERMOBILE', p.mobile)}${opt('LEDGERCONTACT', p.contactPerson)}${opt('LEDSTATENAME', p.state)}${opt('PINCODE', p.pincode)}
</LEDGER>`);
  } else if (p.action === 'Alter') {
    if (!['EMAIL', 'LEDGERMOBILE'].includes(p.field)) error = `Field ${p.field} is not allowed`;
    else xml = wrap('All Masters', `<LEDGER NAME="${esc(p.name)}" ACTION="Alter"><${p.field}>${esc(p.value)}</${p.field}></LEDGER>`);
  } else if (p.action === 'Receipt') {
    const alloc = p.billRef
      ? `<BILLALLOCATIONS.LIST><NAME>${esc(p.billRef)}</NAME><BILLTYPE>Agst Ref</BILLTYPE><AMOUNT>${amt(p.amount)}</AMOUNT></BILLALLOCATIONS.LIST>`
      : `<BILLALLOCATIONS.LIST><BILLTYPE>On Account</BILLTYPE><AMOUNT>${amt(p.amount)}</AMOUNT></BILLALLOCATIONS.LIST>`;
    xml = wrap('Vouchers', `<VOUCHER VCHTYPE="Receipt" ACTION="Create" OBJVIEW="Accounting Voucher View">
<DATE>${esc(p.date)}</DATE><VOUCHERTYPENAME>Receipt</VOUCHERTYPENAME>
<PARTYLEDGERNAME>${esc(p.party)}</PARTYLEDGERNAME><NARRATION>${esc(p.narration)}</NARRATION>
<ALLLEDGERENTRIES.LIST><LEDGERNAME>${esc(p.party)}</LEDGERNAME><ISDEEMEDPOSITIVE>No</ISDEEMEDPOSITIVE><AMOUNT>${amt(p.amount)}</AMOUNT>${alloc}</ALLLEDGERENTRIES.LIST>
<ALLLEDGERENTRIES.LIST><LEDGERNAME>${esc(p.bankLedger)}</LEDGERNAME><ISDEEMEDPOSITIVE>Yes</ISDEEMEDPOSITIVE><AMOUNT>-${amt(p.amount)}</AMOUNT></ALLLEDGERENTRIES.LIST>
</VOUCHER>`);
  } else error = `Unknown action ${p.action}`;
  out.push({ json: { changeKey: r['Change Key'], type: r['Type'], summary: r['Summary'], xml, error }, pairedItem: { item: i } });
});
return out;

// Read Tally's import response: CREATED / ALTERED / ERRORS / LINEERROR
const out = [];
$input.all().forEach((item, i) => {
  const req = $('Build Tally Import XML').itemMatching(i).json;
  const text = String(item.json.data || '');
  const n = t => parseInt((text.match(new RegExp(`<${t}>(\\d+)</${t}>`, 'i')) || [])[1] || '0', 10);
  const lineErr = ((text.match(/<LINEERROR>([\s\S]*?)<\/LINEERROR>/i) || [])[1] || '')
    .replace(/&apos;/g, "'").replace(/&quot;/g, '"').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&amp;/g, '&');
  let ok = false, message;
  if (req.error) message = req.error;
  else if (item.json.error) message = `Tally unreachable: ${String(item.json.error.message || item.json.error).slice(0, 200)}`;
  else {
    ok = n('ERRORS') === 0 && n('EXCEPTIONS') === 0 && n('CREATED') + n('ALTERED') > 0;
    message = ok ? `Created ${n('CREATED')}, altered ${n('ALTERED')}` : `Errors ${n('ERRORS')}, exceptions ${n('EXCEPTIONS')}${lineErr ? ': ' + lineErr.trim() : ''}`;
  }
  out.push({
    json: { 'Change Key': req.changeKey, 'Status': ok ? 'Applied' : 'Failed', 'Applied On': $now.toISO(), 'Tally Response': message.slice(0, 500),
      ok, type: req.type, summary: req.summary },
    pairedItem: { item: i },
  });
});
return out;

// Build the two Tally XML export requests (debtor ledgers + Bills Receivable)
const cfg = $('Set Sync Rules').first().json;
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const company = cfg.tallyCompany ? `<SVCURRENTCOMPANY>${esc(cfg.tallyCompany)}</SVCURRENTCOMPANY>` : '';
const group = esc(cfg.debtorGroup || 'Sundry Debtors');

const ledgerXml = `<ENVELOPE>
<HEADER><VERSION>1</VERSION><TALLYREQUEST>Export</TALLYREQUEST><TYPE>Collection</TYPE><ID>N8NDebtorLedgers</ID></HEADER>
<BODY><DESC>
<STATICVARIABLES><SVEXPORTFORMAT>$$SysName:XML</SVEXPORTFORMAT>${company}</STATICVARIABLES>
<TDL><TDLMESSAGE>
<COLLECTION NAME="N8NDebtorLedgers" ISMODIFY="No">
<TYPE>Ledger</TYPE>
<CHILDOF>${group}</CHILDOF>
<BELONGSTO>Yes</BELONGSTO>
<FETCH>NAME, GUID, ALTERID, PARENT, CLOSINGBALANCE, EMAIL, LEDGERPHONE, LEDGERMOBILE, LEDGERCONTACT, PARTYGSTIN, LEDSTATENAME, PINCODE, ADDRESS, CREDITLIMIT, BILLCREDITPERIOD</FETCH>
</COLLECTION>
</TDLMESSAGE></TDL>
</DESC></BODY>
</ENVELOPE>`;

const billsXml = `<ENVELOPE>
<HEADER><VERSION>1</VERSION><TALLYREQUEST>Export</TALLYREQUEST><TYPE>Data</TYPE><ID>Bills Receivable</ID></HEADER>
<BODY><DESC>
<STATICVARIABLES><SVEXPORTFORMAT>$$SysName:XML</SVEXPORTFORMAT>${company}<SVTODATE>${$today.toFormat('yyyyLLdd')}</SVTODATE></STATICVARIABLES>
</DESC></BODY>
</ENVELOPE>`;

return [{ json: { ledgerXml, billsXml } }];

// Parse Tally's XML responses into ledgers and open bills.
// Tally sign convention: debit (receivable) amounts come back negative.
const ledgerText = String($('Export Debtor Ledgers').first().json.data || '');
const billText = String($input.first().json.data || '');
if (!/<ENVELOPE/i.test(ledgerText)) throw new Error('Tally did not return XML. Check that Tally is running, the company is open and the HTTP port (default 9000) is enabled and reachable from n8n.');
const err = ledgerText.match(/<LINEERROR>([\s\S]*?)<\/LINEERROR>/i);
if (err) throw new Error('Tally error: ' + err[1]);

const dec = s => String(s || '').replace(/&#13;|&#10;/g, ' ').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&apos;/g, "'").replace(/&#(\d+);/g, (m, c) => String.fromCharCode(c)).trim();
const tag = (block, name) => { const m = block.match(new RegExp(`<${name}(?:\\s[^>]*)?>([\\s\\S]*?)</${name}>`, 'i')); return m ? dec(m[1]) : ''; };
const num = v => { const n = parseFloat(String(v || '').replace(/[^0-9.\-]/g, '')); return isNaN(n) ? 0 : n; };
const tallyDate = s => {
  for (const f of ['d-LLL-yy', 'd-LLL-yyyy', 'yyyyLLdd', 'd-L-yyyy']) {
    const d = DateTime.fromFormat(String(s || '').trim(), f);
    if (d.isValid) return d.toISODate();
  }
  return '';
};

const ledgers = [];
const re = /<LEDGER\s+NAME="([^"]*)"[^>]*>([\s\S]*?)<\/LEDGER>/gi;
let m;
while ((m = re.exec(ledgerText))) {
  const b = m[2];
  const addr = (b.match(/<ADDRESS\.LIST[^>]*>([\s\S]*?)<\/ADDRESS\.LIST>/i) || ['', ''])[1];
  const lines = [...addr.matchAll(/<ADDRESS[^>]*>([\s\S]*?)<\/ADDRESS>/gi)].map(x => dec(x[1])).filter(Boolean);
  ledgers.push({
    name: dec(m[1]) || tag(b, 'NAME'),
    guid: tag(b, 'GUID'),
    alterId: tag(b, 'ALTERID'),
    parent: tag(b, 'PARENT'),
    balance: Math.round(-num(tag(b, 'CLOSINGBALANCE')) * 100) / 100,   // + means customer owes us
    email: tag(b, 'EMAIL').split(/[;,]/)[0].trim().toLowerCase(),
    phone: tag(b, 'LEDGERMOBILE') || tag(b, 'LEDGERPHONE'),
    contactPerson: tag(b, 'LEDGERCONTACT'),
    gstin: tag(b, 'PARTYGSTIN').toUpperCase(),
    state: tag(b, 'LEDSTATENAME'),
    pincode: tag(b, 'PINCODE'),
    address: lines.join(', '),
    creditLimit: Math.abs(num(tag(b, 'CREDITLIMIT'))),
    creditPeriod: tag(b, 'BILLCREDITPERIOD'),
  });
}
if (!ledgers.length) throw new Error('Tally returned no ledgers under the debtor group. Check debtorGroup and tallyCompany in Set Sync Rules.');

// Bills Receivable: BILLFIXED (date, ref, party) followed by BILLCL, BILLDUE, BILLOVERDUE
const bills = [];
for (const chunk of billText.split(/<BILLFIXED>/i).slice(1)) {
  const party = tag(chunk, 'BILLPARTY');
  const ref = tag(chunk, 'BILLREF');
  if (!party || !ref) continue;
  const amount = Math.round(-num(tag(chunk, 'BILLCL')) * 100) / 100;
  if (Math.abs(amount) < 0.01) continue;
  bills.push({
    party, ref, amount,
    billDate: tallyDate(tag(chunk, 'BILLDATE')),
    dueDate: tallyDate(tag(chunk, 'BILLDUE')),
    overdueDays: parseInt(tag(chunk, 'BILLOVERDUE'), 10) || 0,
  });
}
return [{ json: { ledgers, bills, ledgerCount: ledgers.length, billCount: bills.length } }];

// Sync engine: link Tally ledgers to GHL contacts, compute AR per customer,
// three-way merge contact fields, and queue anything that would change Tally.
const cfg = $('Set Sync Rules').first().json;
const { ledgers, bills } = $('Parse Tally Data').first().json;
const todayISO = $today.toISODate();
const nowISO = $now.toISO();
const lower = s => String(s || '').trim().toLowerCase();
const digits = s => String(s || '').replace(/\D/g, '').slice(-10);
const normName = s => lower(s).replace(/&/g, 'and').replace(/\b(pvt|private|ltd|limited|llp|co|company|the|m\/s|ms)\b/g, '').replace(/[^a-z0-9]/g, '');
const r2 = n => Math.round((Number(n) || 0) * 100) / 100;
const flat = (name, key) => { try { return $(name).all().flatMap(i => (Array.isArray(i.json[key]) ? i.json[key] : [])); } catch (e) { return []; } };
const uniq = (list, key) => Object.values(Object.fromEntries(list.filter(x => x && x[key]).map(x => [x[key], x])));

const contacts = uniq(flat('Fetch GHL Contacts', 'contacts'), 'id');
const txns = uniq($input.all().flatMap(i => (Array.isArray(i.json.data) ? i.json.data : [])), '_id');
const mapRows = $('Read Customer Map').all().map(i => i.json).filter(r => r['Tally Ledger'] || r['Tally GUID']);
const queueKeys = new Set($('Read Change Queue').all().map(i => i.json['Change Key']).filter(Boolean).map(String));
const prevBills = $('Read Bills').all().map(i => i.json).filter(r => r['Bill Key']);

const F = {
  balance: cfg.cfTallyBalance, overdue: cfg.cfOverdueAmount, oldestDue: cfg.cfOldestDueDate, maxOverdue: cfg.cfMaxOverdueDays,
  ledger: cfg.cfTallyLedger, status: cfg.cfCreditStatus, synced: cfg.cfLastSynced,
};
const MANAGED_TAGS = [cfg.tagCurrent, cfg.tagOverdue30, cfg.tagOverdue60, cfg.tagOverdue90, cfg.tagCreditHold, cfg.tagAdvance].filter(Boolean);

// ---------- Indexes ----------
const mapByGuid = Object.fromEntries(mapRows.filter(r => r['Tally GUID']).map(r => [String(r['Tally GUID']), r]));
const mapByName = Object.fromEntries(mapRows.map(r => [lower(r['Tally Ledger']), r]));
const cById = Object.fromEntries(contacts.map(c => [c.id, c]));
const index = (fn) => { const m = {}; for (const c of contacts) { const k = fn(c); if (k) (m[k] = m[k] || []).push(c); } return m; };
const cByEmail = index(c => lower(c.email));
const cByPhone = index(c => digits(c.phone));
const cByName = index(c => normName(c.companyName) || normName(c.contactName || `${c.firstName || ''} ${c.lastName || ''}`));
const one = list => (list && list.length === 1 ? list[0] : null);
const billsByParty = {};
for (const b of bills) (billsByParty[lower(b.party)] = billsByParty[lower(b.party)] || []).push(b);

const out = [];
const push = (kind, j) => out.push({ json: { kind, ...j } });
const conflict = (key, fields) => push('conflict', { 'Conflict Key': key, 'Detected On': todayISO, 'Status': 'Open', ...fields });
const queue = (key, type, ledger, contactId, summary, payload) => {
  if (queueKeys.has(key)) return false;
  queueKeys.add(key);
  push('queue', { 'Change Key': key, 'Created On': nowISO, 'Type': type, 'Tally Ledger': ledger, 'GHL Contact ID': contactId || '',
    'Summary': summary, 'Payload': JSON.stringify(payload), 'Status': cfg.autoApproveTallyWrites ? 'Approved' : 'Pending' });
  return true;
};
const stats = { linked: 0, newLinks: 0, ghlUpdates: 0, ghlCreates: 0, queued: 0, conflicts: 0, newHolds: [], unlinkedPayments: 0 };
const linkedContactIds = new Set();
const ledgerByContact = {};

// ---------- Tally -> GHL ----------
for (const L of ledgers) {
  const row = mapByGuid[L.guid] || mapByName[lower(L.name)] || {};
  let c = null, method = '';
  if (row['GHL Contact ID'] && cById[row['GHL Contact ID']]) { c = cById[row['GHL Contact ID']]; method = 'Linked'; }
  else if (L.email && one(cByEmail[L.email])) { c = one(cByEmail[L.email]); method = 'Email'; }
  else if (digits(L.phone) && one(cByPhone[digits(L.phone)])) { c = one(cByPhone[digits(L.phone)]); method = 'Phone'; }
  else if (normName(L.name) && one(cByName[normName(L.name)])) { c = one(cByName[normName(L.name)]); method = 'Company name'; }
  if (c && linkedContactIds.has(c.id)) {
    conflict(`duplicate-link|${c.id}`, { 'Type': 'Two ledgers match one contact', 'Tally Ledger': L.name, 'GHL Contact ID': c.id,
      'Tally Value': L.name, 'GHL Value': c.companyName || c.email || '', 'Detail': `Contact already linked to ${ledgerByContact[c.id]}. Link one manually in Customers tab.` });
    stats.conflicts++;
    c = null; method = '';
  }
  if (c) { linkedContactIds.add(c.id); ledgerByContact[c.id] = L.name; stats.linked++; if (method !== 'Linked') stats.newLinks++; }

  // AR from bills
  const bl = billsByParty[lower(L.name)] || [];
  const bucket = { b30: 0, b60: 0, b90: 0, b90p: 0 };
  let overdue = 0, maxOverdue = 0, oldestDue = '';
  for (const b of bl) {
    if (b.amount <= 0) continue;
    if (b.overdueDays > 0) {
      overdue += b.amount;
      maxOverdue = Math.max(maxOverdue, b.overdueDays);
      const k = b.overdueDays <= 30 ? 'b30' : b.overdueDays <= 60 ? 'b60' : b.overdueDays <= 90 ? 'b90' : 'b90p';
      bucket[k] += b.amount;
    }
    if (b.dueDate && (!oldestDue || b.dueDate < oldestDue)) oldestDue = b.dueDate;
  }
  const overLimit = L.creditLimit > 0 && L.balance > L.creditLimit;
  const hold = maxOverdue >= cfg.creditHoldDays || overLimit;
  const status = L.balance < -0.5 ? 'Advance' : L.balance <= 0.5 ? 'Clear' : hold ? 'Credit Hold' : overdue > 0 ? 'Overdue' : 'Current';
  if (hold && row['Credit Status'] && row['Credit Status'] !== 'Credit Hold') stats.newHolds.push(`${L.name} (${maxOverdue} days, ${r2(L.balance)})`);

  // Three-way merge of email and phone. Snapshot = value both sides agreed on at last sync.
  const snap = { email: lower(row['Snapshot Email']), phone: digits(row['Snapshot Phone']) };
  const tv = { email: L.email, phone: digits(L.phone) };
  const newSnap = { ...snap };
  const ghlFieldUpdates = {};
  if (c) {
    const gv = { email: lower(c.email), phone: digits(c.phone) };
    for (const f of ['email', 'phone']) {
      const t = tv[f], g = gv[f], s = snap[f];
      if (t === g) { newSnap[f] = t; continue; }
      const tChanged = t !== s, gChanged = g !== s;
      if (!s && !row['Snapshot Email'] && !row['Snapshot Phone'] && t && g) {
        conflict(`${f}|${L.guid || L.name}|${t}|${g}`, { 'Type': `${f} differs on first link`, 'Tally Ledger': L.name, 'GHL Contact ID': c.id,
          'Tally Value': t, 'GHL Value': g, 'Detail': 'Fix one side; the sync will pick it up next run.' });
        stats.conflicts++;
      } else if (t && (tChanged && !gChanged || !g)) {
        ghlFieldUpdates[f] = f === 'email' ? L.email : (cfg.defaultCountryCode || '+91') + digits(L.phone);   // Tally changed -> GHL
        newSnap[f] = t;
      } else if (g && (gChanged && !tChanged || !t)) {
        if (cfg.syncContactFieldsToTally && queue(`alter|${L.guid || L.name}|${f}|${g}`, 'Alter Ledger', L.name, c.id,
          `Update ${f} on Tally ledger "${L.name}" from "${t || '(blank)'}" to "${f === 'email' ? c.email : c.phone}"`,
          { action: 'Alter', name: L.name, field: f === 'email' ? 'EMAIL' : 'LEDGERMOBILE', value: f === 'email' ? c.email : c.phone })) stats.queued++;
      } else {
        conflict(`${f}|${L.guid || L.name}|${t}|${g}`, { 'Type': `${f} changed on both sides`, 'Tally Ledger': L.name, 'GHL Contact ID': c.id,
          'Tally Value': t, 'GHL Value': g, 'Detail': `Last agreed value: ${s || '(none)'}. Correct one side.` });
        stats.conflicts++;
      }
    }

    // Custom fields: only send what changed
    const cur = Object.fromEntries((c.customFields || []).map(x => [x.id, x.value]));
    const want = {};
    if (F.balance) want[F.balance] = r2(L.balance);
    if (F.overdue) want[F.overdue] = r2(overdue);
    if (F.maxOverdue) want[F.maxOverdue] = maxOverdue;
    if (F.oldestDue) want[F.oldestDue] = oldestDue;
    if (F.ledger) want[F.ledger] = L.name;
    if (F.status) want[F.status] = status;
    const changed = Object.entries(want).filter(([id, v]) => String(cur[id] ?? '') !== String(v ?? ''));
    if (changed.length || Object.keys(ghlFieldUpdates).length) {
      const body = {};
      if (changed.length) body.customFields = [...changed, ...(F.synced ? [[F.synced, todayISO]] : [])].map(([id, v]) => ({ id, field_value: v }));
      Object.assign(body, ghlFieldUpdates);
      push('ghl_update', { contactId: c.id, ledger: L.name, body });
      stats.ghlUpdates++;
    }

    // AR tags
    const desired = new Set();
    if (status === 'Current' && cfg.tagCurrent) desired.add(cfg.tagCurrent);
    if (status === 'Advance' && cfg.tagAdvance) desired.add(cfg.tagAdvance);
    if (maxOverdue > 0) desired.add(maxOverdue <= 30 ? cfg.tagOverdue30 : maxOverdue <= 60 ? cfg.tagOverdue60 : cfg.tagOverdue90);
    if (hold && cfg.tagCreditHold) desired.add(cfg.tagCreditHold);
    const have = new Set((c.tags || []).map(lower));
    const add = [...desired].filter(t => t && !have.has(lower(t)));
    const remove = MANAGED_TAGS.filter(t => have.has(lower(t)) && !desired.has(t));
    if (add.length) push('tags_add', { contactId: c.id, tags: add });
    if (remove.length) push('tags_remove', { contactId: c.id, tags: remove });
  } else if (cfg.createContactsInGhl && (L.email || digits(L.phone))) {
    const body = { locationId: cfg.ghlLocationId, name: L.contactPerson || L.name, companyName: L.name, source: 'Tally sync',
      tags: [cfg.tagFromTally, ...(maxOverdue > 0 ? [maxOverdue <= 30 ? cfg.tagOverdue30 : maxOverdue <= 60 ? cfg.tagOverdue60 : cfg.tagOverdue90] : [])].filter(Boolean) };
    if (L.email) body.email = L.email;
    if (digits(L.phone)) body.phone = (cfg.defaultCountryCode || '+91') + digits(L.phone);
    if (L.address) body.address1 = L.address;
    if (L.pincode) body.postalCode = L.pincode;
    if (L.state) body.state = L.state;
    const cf = [[F.balance, r2(L.balance)], [F.overdue, r2(overdue)], [F.ledger, L.name], [F.status, status], [F.synced, todayISO]].filter(([id]) => id);
    if (cf.length) body.customFields = cf.map(([id, v]) => ({ id, field_value: v }));
    push('ghl_create', { guid: L.guid, ledger: L.name, body });
    stats.ghlCreates++;
    newSnap.email = tv.email; newSnap.phone = tv.phone;
  }

  push('customer_row', {
    'Tally GUID': L.guid, 'Tally Ledger': L.name, 'Tally Alter ID': L.alterId, 'GHL Contact ID': c ? c.id : (row['GHL Contact ID'] || ''),
    'Match Method': method || (row['GHL Contact ID'] ? 'Linked (contact not found)' : 'Unlinked'),
    'Email': L.email, 'Phone': L.phone, 'GSTIN': L.gstin, 'State': L.state,
    'Closing Balance': r2(L.balance), 'Overdue Amount': r2(overdue), 'Overdue 1-30': r2(bucket.b30), 'Overdue 31-60': r2(bucket.b60),
    'Overdue 61-90': r2(bucket.b90), 'Overdue 90+': r2(bucket.b90p), 'Oldest Due Date': oldestDue, 'Max Overdue Days': maxOverdue,
    'Open Bills': bl.filter(b => b.amount > 0).length, 'Credit Limit': L.creditLimit || '', 'Credit Status': status,
    'Snapshot Email': newSnap.email || '', 'Snapshot Phone': newSnap.phone || '', 'Last Synced': nowISO,
  });
}

// ---------- Bills mirror (open + newly cleared) ----------
const seen = new Set();
for (const b of bills) {
  const key = `${b.party}|${b.ref}`;
  seen.add(key);
  push('bill_row', { 'Bill Key': key, 'Party': b.party, 'Bill Ref': b.ref, 'Bill Date': b.billDate, 'Due Date': b.dueDate,
    'Outstanding': b.amount, 'Overdue Days': b.overdueDays, 'Status': b.amount < 0 ? 'Advance' : b.overdueDays > 0 ? 'Overdue' : 'Open',
    'Cleared On': '', 'Last Seen': todayISO });
}
for (const p of prevBills) {
  if (seen.has(String(p['Bill Key'])) || p['Status'] === 'Cleared') continue;
  push('bill_row', { 'Bill Key': p['Bill Key'], 'Party': p['Party'], 'Bill Ref': p['Bill Ref'], 'Bill Date': p['Bill Date'], 'Due Date': p['Due Date'],
    'Outstanding': 0, 'Overdue Days': 0, 'Status': 'Cleared', 'Cleared On': todayISO, 'Last Seen': todayISO });
}

// ---------- GHL -> Tally: new customers ----------
const ledgerNames = new Set(ledgers.map(l => normName(l.name)));
for (const c of contacts) {
  if (linkedContactIds.has(c.id)) continue;
  if (!(c.tags || []).map(lower).includes(lower(cfg.customerTag))) continue;
  const name = (c.companyName || c.contactName || `${c.firstName || ''} ${c.lastName || ''}`).trim();
  if (!name) continue;
  if (ledgerNames.has(normName(name))) {
    conflict(`name-only|${c.id}`, { 'Type': 'Possible duplicate ledger', 'Tally Ledger': name, 'GHL Contact ID': c.id, 'Tally Value': name, 'GHL Value': c.email || c.phone || '',
      'Detail': 'A ledger with a similar name exists but email/phone do not match. Link manually in the Customers tab.' });
    stats.conflicts++;
    continue;
  }
  if (queue(`create|${c.id}`, 'Create Ledger', name, c.id, `Create debtor ledger "${name}" (${c.email || c.phone || 'no contact details'}) under ${cfg.debtorGroup}`,
    { action: 'Create', name, parent: cfg.debtorGroup, email: c.email || '', mobile: digits(c.phone), address: [c.address1, c.city].filter(Boolean).join(', '),
      state: c.state || '', pincode: c.postalCode || '', contactPerson: `${c.firstName || ''} ${c.lastName || ''}`.trim() })) stats.queued++;
}

// ---------- GHL payments -> Tally receipts ----------
for (const t of txns) {
  if (lower(t.status) !== 'succeeded' || !t.amount) continue;
  if (t.liveMode === false && !cfg.includeTestPayments) continue;
  const key = `receipt|${t._id}`;
  if (queueKeys.has(key)) continue;
  const ledgerName = ledgerByContact[t.contactId];
  if (!ledgerName) {
    conflict(`payment-unlinked|${t._id}`, { 'Type': 'GHL payment from an unlinked contact', 'Tally Ledger': '', 'GHL Contact ID': t.contactId || '',
      'Tally Value': '', 'GHL Value': `${t.currency || ''} ${t.amount} ${t.contactName || t.contactEmail || ''}`,
      'Detail': 'Link this contact to a Tally ledger, then the receipt will be queued automatically.' });
    stats.unlinkedPayments++;
    continue;
  }
  const amount = r2(t.amount);
  const open = (billsByParty[lower(ledgerName)] || []).filter(b => b.amount > 0);
  const byRef = open.find(b => t.entitySourceName && lower(t.entitySourceName).includes(lower(b.ref)));
  const byAmount = open.filter(b => Math.abs(b.amount - amount) < 0.5);
  const bill = byRef || (byAmount.length === 1 ? byAmount[0] : null);
  const date = DateTime.fromISO(t.createdAt || nowISO);
  if (queue(key, 'Receipt Voucher', ledgerName, t.contactId,
    `Receipt of ${amount} from "${ledgerName}" on ${date.toISODate()} into "${cfg.receiptBankLedger}"${bill ? ` against bill ${bill.ref}` : ' on account'}`,
    { action: 'Receipt', date: date.toFormat('yyyyLLdd'), party: ledgerName, amount, bankLedger: cfg.receiptBankLedger,
      billRef: bill ? bill.ref : '', narration: `GHL payment ${t._id}${t.entitySourceName ? ' - ' + t.entitySourceName : ''}`.slice(0, 240) })) stats.queued++;
}

const pendingBefore = $('Read Change Queue').all().map(i => i.json).filter(r => r['Status'] === 'Pending').length;
push('summary', {
  runAt: nowISO, ledgers: ledgers.length, openBills: bills.length, contacts: contacts.length, ...stats,
  pendingTotal: pendingBefore + (cfg.autoApproveTallyWrites ? 0 : stats.queued),
  totalReceivable: r2(ledgers.reduce((s, l) => s + Math.max(l.balance, 0), 0)),
  totalOverdue: r2(bills.filter(b => b.overdueDays > 0 && b.amount > 0).reduce((s, b) => s + b.amount, 0)),
});
return out;

// Store the GHL contact ID created for a Tally ledger
const out = [];
$input.all().forEach((item, i) => {
  const req = $('Route by Record Type').itemMatching(i).json;
  const id = item.json.contact && item.json.contact.id;
  if (!id) return;
  out.push({ json: { 'Tally GUID': req.guid, 'GHL Contact ID': id, 'Match Method': item.json.new ? 'Created in GHL' : 'Upserted in GHL' }, pairedItem: { item: i } });
});
return out;

// Slack message only when something needs a person
const s = $input.first().json;
const cfg = $('Set Sync Rules').first().json;
let applied = [];
try { applied = $('Parse Import Result').all().map(i => i.json); } catch (e) {}
const ok = applied.filter(a => a.ok), failed = applied.filter(a => !a.ok);
const inr = n => 'Rs. ' + Number(n || 0).toLocaleString('en-IN', { maximumFractionDigits: 0 });
const lines = [
  `:arrows_counterclockwise: *Tally <> GHL sync* - ${$now.toFormat('d LLL, HH:mm')}`,
  `${s.ledgers} ledgers, ${s.openBills} open bills | Receivable ${inr(s.totalReceivable)}, overdue ${inr(s.totalOverdue)}`,
  `GHL: ${s.linked} linked (${s.newLinks} new), ${s.ghlUpdates} updated, ${s.ghlCreates} created`,
];
if (ok.length) lines.push(`:white_check_mark: Posted to Tally: ${ok.length} (${ok.map(a => a.type).join(', ')})`);
if (failed.length) lines.push(`:x: *${failed.length} Tally write(s) failed:*\n${failed.slice(0, 5).map(a => `- ${a.summary}: ${a['Tally Response']}`).join('\n')}`);
if (s.queued) lines.push(`:inbox_tray: ${s.queued} new change(s) queued for Tally. *${s.pendingTotal} awaiting approval* in the Tally Change Queue tab.`);
if (s.conflicts) lines.push(`:warning: ${s.conflicts} conflict(s) need a decision (Conflicts tab)`);
if (s.unlinkedPayments) lines.push(`:moneybag: ${s.unlinkedPayments} GHL payment(s) from contacts not linked to a Tally ledger`);
if (s.newHolds.length) lines.push(`:no_entry: *Now on credit hold:* ${s.newHolds.slice(0, 8).join(', ')}`);
const notify = ok.length || failed.length || s.queued || s.conflicts || s.unlinkedPayments || s.newHolds.length;
return [{ json: { notify: !!notify, text: lines.join('\n') } }];
